import React, { useState } from 'react';

// Create the ConcurrentDemo component function here
function ConcurrentDemo(): JSX.Element {
  // Initialize count state with useState here
  const [count, setCount] = useState<number>(0);
  // Add loading state here
  const [loading, setLoading] = useState<boolean>(false);

  // Define simulateFetch handler function here
  const simulateFetch = () => {
    setLoading(true);
    setTimeout(() => {
      setCount(prev => prev + 1);
      setLoading(false);
    }, 1000);
  };

  // Define resetCount handler function here
  const resetCount = () => {
    setCount(0);
  };

  return (
    <div>
      <h1>Concurrent Mode Gotchas</h1>
      <p>Current count: {count}</p>
      <button onClick={simulateFetch} disabled={loading}>
        {loading ? 'Fetching...' : 'Fetch Data'}
      </button>
      {/* Add reset button here */}
    </div>
  );
}

